package dev.juanpablocorrea.portfolio.contact.domain.model;

import dev.juanpablocorrea.portfolio.contact.domain.error.InvalidValueException;

import java.util.UUID;
import java.util.regex.Pattern;

/**
 * Identity of a contact message. It is generated by the browser (one id per form),
 * which makes the submission idempotent: a retried request cannot create a duplicate.
 */
public record MessageId(UUID value) {

    private static final Pattern CANONICAL_UUID =
            Pattern.compile("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$");

    public MessageId {
        if (value == null) {
            throw new InvalidValueException("Falta el identificador del envío.");
        }
    }

    public static MessageId parse(String raw) {
        String candidate = raw == null ? "" : raw.strip();
        if (!CANONICAL_UUID.matcher(candidate).matches()) {
            throw new InvalidValueException("El identificador del envío no es válido.");
        }
        return new MessageId(UUID.fromString(candidate));
    }

    public static MessageId generate() {
        return new MessageId(UUID.randomUUID());
    }
}
